  // ── 💪 exercise — ported from oz0.3 health-activity.html (the layout Sum liked)
  window.CARD_BUILDERS.exercise = function buildExercise() {
    const MET_GOAL = 600   // weekly MET-min — the clinical dose (WHO ~150 min moderate ≈ 500–600). NO STEPS: toto tracks what a clinician tracks.
    const TL_START = 6, TL_END = 22, TL_MINS = (TL_END - TL_START) * 60
    const metMin = sess => (sess || []).reduce((a, s) => a + (+s.met || 0) * (+s.duration_min || 0), 0)   // MET-minutes = intensity × duration
    const DAY_ABR  = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
    const DEFAULT_PRESETS = [
      { type: 'Yoga Teaching',    dur: 60, met: 3.5 },
      { type: 'Yoga Flow',        dur: 45, met: 3.0 },
      { type: 'Yoga Restorative', dur: 60, met: 1.5 },
      { type: 'Walk',             dur: 30, met: 3.5 },
      { type: 'Walk Fast',        dur: 20, met: 5.0 },
      { type: 'Hügelkultur',           dur: 60, met: 5.5 },
      { type: 'Garden',           dur: 60, met: 3.5 },
      { type: 'Strength',         dur: 30, met: 4.5 },
      { type: 'HIIT',             dur: 20, met: 7.0 },
    ]
    // presets are user-editable — ✕ to delete (left page) · "save as preset" from the form (right page) → persisted
    const loadPresets = () => { try { const s = localStorage.getItem('toto_ex_presets'); if (s) { const p = JSON.parse(s); if (Array.isArray(p)) return p } } catch (_) {} return DEFAULT_PRESETS.slice() }
    const savePresets = () => { try { localStorage.setItem('toto_ex_presets', JSON.stringify(PRESETS)) } catch (_) {} }
    let PRESETS = loadPresets()
    // mock week — Sum's real patterns (yoga ×5/wk, hügelkultur beds + garden = heavy by-hand permaculture labor)
    const MOCK = [
      { date: '2026-03-23', active_min: 90,  sessions: [{ type: 'Yoga Teaching', start: '8:30 AM',  duration_min: 60, met: 3.5 }, { type: 'Yoga Teaching',  start: '5:30 PM',  duration_min: 60, met: 3.5 }] },
      { date: '2026-03-24', active_min: 30,  sessions: [{ type: 'Walk',          start: '10:00 AM', duration_min: 30, met: 3.5 }] },
      { date: '2026-03-25', active_min: 180, sessions: [{ type: 'Yoga Teaching', start: '8:30 AM',  duration_min: 60, met: 3.5 }, { type: 'Yoga Flow',     start: '2:00 PM',  duration_min: 45, met: 3.0 }, { type: 'Studio Clean', start: '4:00 PM', duration_min: 60, met: 3.5 }] },
      { date: '2026-03-26', active_min: 45,  sessions: [{ type: 'Yoga Teaching', start: '5:30 PM',  duration_min: 45, met: 3.5 }] },
      { date: '2026-03-27', active_min: 60,  sessions: [{ type: 'Hügelkultur',        start: '11:00 AM', duration_min: 60, met: 5.5 }] },
      { date: '2026-03-28', active_min: 45,  sessions: [{ type: 'Garden',        start: '2:00 PM',  duration_min: 45, met: 3.5 }] },
      { date: '2026-03-29', active_min: 60,  sessions: [{ type: 'Yoga Teaching', start: '8:30 AM',  duration_min: 60, met: 3.5 }] },
      // real Samsung Watch sessions from oz0.3/data/activity-data.json (Apr 2026, baked with consent)
      { date: '2026-04-07', active_min: 13,  sessions: [{ type: 'Walk', start: '4:34 PM', duration_min: 13, met: 3.8, source: 'samsung_watch', hr_mean: 112, distance_m: 1033 }] },
      { date: '2026-04-09', active_min: 30,  sessions: [{ type: 'Walk', start: '1:24 PM', duration_min: 30, met: 3.8, source: 'samsung_watch', hr_mean: 107, distance_m: 2457 }] },
      { date: '2026-04-10', active_min: 80,  sessions: [{ type: 'Walk', start: '4:12 PM', duration_min: 15, met: 3.8, source: 'samsung_watch', hr_mean: 112, distance_m: 1229 }, { type: 'Walk', start: '4:36 PM', duration_min: 17, met: 3.8, source: 'samsung_watch', hr_mean: 107, distance_m: 1110 }, { type: 'Walk', start: '5:32 PM', duration_min: 48, met: 3.8, source: 'samsung_watch', hr_mean: 109, distance_m: 3759 }] },
    ]
    window.DASH_EX_DAYS = MOCK   // expose the day×session data so the 🧘 wellness master report can read it

    function actCls(type) {
      const t = (type || '').toLowerCase()
      if (/yoga|walk|garden|studio|clean|light|stretch/.test(t)) return 't-light'
      if (/bike|cycl|swim|row|moderate|ellip/.test(t))           return 't-mod'
      if (/strength|weight|lift|interval|circuit|hugel|hügel|dig|permac/.test(t)) return 't-hard'
      if (/hiit|run|martial|kickbox|cross/.test(t))               return 't-intense'
      return 't-mod'
    }

    function toMins(str) {
      const m = (str || '').match(/(\d+):(\d+)\s*(AM|PM)/i); if (!m) return null
      let h = parseInt(m[1]); const min = parseInt(m[2]), pm = m[3].toUpperCase() === 'PM'
      if (pm && h !== 12) h += 12; if (!pm && h === 12) h = 0
      return (h * 60 + min) - TL_START * 60
    }

    // HR→MET-min receipt: the clinical derivation that sells the metric (spec #19)
    const metReceipt = s => s.hr_mean
      ? `${s.hr_mean} bpm × ${s.duration_min} min → ${s.met} MET → ${Math.round(s.met * s.duration_min)} MET-min`
      : ''

    let end = '2026-03-29'   // opens on the demo yoga week; 'today' → real current week (spec #20)

    function getWeek() {
      const logged = JSON.parse(localStorage.getItem('toto_exercise_log') || '[]')
      const realToday = todayIso()
      return isoSpan(7, end).map(iso => {
        const d = new Date(iso + 'T12:00:00')
        const base = MOCK.find(w => w.date === iso) || { date: iso, active_min: 0, sessions: [] }
        const extra = logged.filter(s => s.date === iso)
        const extraMin = extra.reduce((a, s) => a + (s.duration_min || 0), 0)
        return { date: iso, dayName: DAY_ABR[d.getDay()], dateLabel: (d.getMonth() + 1) + '/' + d.getDate(), isToday: iso === realToday, active_min: (base.active_min || 0) + extraMin, sessions: [...base.sessions, ...extra] }
      })
    }

    function buildBody() {
      const days     = getWeek()
      const today    = days[days.length - 1]
      const totSess  = days.reduce((s, d) => s + d.sessions.length, 0)
      const totAct   = days.reduce((s, d) => s + (d.active_min || 0), 0)
      const actDays  = days.filter(d => d.active_min > 0).length
      const todayMM  = Math.round(metMin(today.sessions))
      const weekMM   = Math.round(days.reduce((s, d) => s + metMin(d.sessions), 0))
      const weekPct  = Math.min(100, Math.round(weekMM / MET_GOAL * 100))
      const avgMM    = actDays ? Math.round(weekMM / actDays) : 0
      const bestDay  = [...days].sort((a, b) => metMin(b.sessions) - metMin(a.sessions))[0]
      const realSess = days.flatMap(d => d.sessions).find(s => s.hr_mean)   // first real watch session this week

      const axis = Array.from({ length: 9 }, (_, i) => {
        const h = TL_START + i * 2, ampm = h >= 12 ? 'PM' : 'AM', h12 = h % 12 || 12
        return `<div class="ex-time-lbl">${h12}${ampm}</div>`
      }).join('')

      const dayCols = days.map(day => {
        const blocks = day.sessions.map(s => {
          const off = toMins(s.start); if (off === null || off < 0) return ''
          const topPct = Math.max(0, off / TL_MINS * 100)
          const htPct  = Math.min((s.duration_min || 30) / TL_MINS * 100, 100 - topPct)
          if (htPct < 0.3) return ''
          const ht = Math.max(htPct, 1.2)
          const showLabel = ht > 6, showDur = ht > 12
          const tip = [s.type, s.start, s.duration_min + 'min', metReceipt(s), s.source].filter(Boolean).join(' · ')
          return `<div class="ex-act-block ${actCls(s.type)}" style="top:${topPct.toFixed(1)}%;height:${ht.toFixed(1)}%" title="${tip}">${showLabel ? `<span class="ex-act-lbl">${s.type}</span>${showDur ? `<span class="ex-act-dur">${s.duration_min}m</span>` : ''}` : ''}</div>`
        }).join('')
        const dmm = Math.round(metMin(day.sessions))
        return `<div class="ex-day-col">
          <div class="ex-day-head${day.isToday ? ' today' : ''}"><span>${day.dayName}</span><span class="ex-day-date">${day.dateLabel}</span></div>
          <div class="ex-tl-slot">${blocks}</div>
          <div class="ex-step-cell${dmm > 0 ? ' has' : ''}" title="total MET-min this day">${dmm > 0 ? `<b>${dmm}</b><span>MET-min</span>` : '—'}</div>
        </div>`
      }).join('')

      const bestLbl = bestDay && metMin(bestDay.sessions) > 0
        ? (() => { const bd = new Date(bestDay.date + 'T12:00:00'); return DAY_ABR[bd.getDay()] + ' ' + (bd.getMonth() + 1) + '/' + bd.getDate() })()
        : '—'
      const presetsHTML = PRESETS.map((p, i) => `<button class="ex-preset" data-type="${p.type}" data-dur="${p.dur}" data-met="${p.met}">${p.type.toLowerCase()}<span class="ex-preset-x" data-del="${i}" title="delete preset">✕</span></button>`).join('')

      // ⭐ THE DRAFT, MADE VISIBLE (Sum 2026-08-25: "card repaint on every edit so I can watch it fill each
      //    section"). The exercise_in_* tools build a draft in toto_exercise_draft field by field, and this
      //    card only ever rendered the COMMITTED log — so there was nothing to watch fill, and nothing to
      //    repaint. A repaint with no draft on screen would have looked like the fix worked and changed
      //    nothing on his screen until save. So the strip comes first, above the scope: every slot the bot
      //    has filled lights up, every slot it hasn't sits dim, and the conductor's oz-card-dirty repaints
      //    it on every single edit. It disappears on its own when exercise_save clears the draft.
      const exDraft = (() => { try { return JSON.parse(localStorage.getItem('toto_exercise_draft') || '{}') || {} } catch (_) { return {} } })()
      const DRAFT_SLOTS = [['type', 'activity'], ['duration_min', 'minutes'], ['met', 'intensity'], ['start', 'start time'], ['date', 'date']]
      const escD = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
      const filled = DRAFT_SLOTS.filter(f => exDraft[f[0]] != null && exDraft[f[0]] !== '')
      const draftStrip = !filled.length ? '' : `
        <div class="dash-block ex-draft" role="status" aria-live="polite">
          <div class="ex-draft-top">\u270e logging a workout — ${filled.length} of ${DRAFT_SLOTS.length} filled${(exDraft.type && exDraft.duration_min) ? '' : ' · needs an activity and minutes to save'}</div>
          <div class="ex-draft-slots">
            ${DRAFT_SLOTS.map(([k, lbl]) => {
              const on = exDraft[k] != null && exDraft[k] !== ''
              return `<div class="ex-draft-slot${on ? ' on' : ''}"><span class="ex-draft-lbl">${lbl}</span><span class="ex-draft-val">${on ? escD(exDraft[k]) : '\u2014'}</span></div>`
            }).join('')}
          </div>
        </div>`

      return `
        ${sNav(end)}
        ${draftStrip}
        <div class="dash-sub dash-osc">
        <div class="dash-sub-head" data-sub="osc">OSCILLOSCOPE<span class="dash-sub-caret">▼</span></div>
        <div class="dash-sub-body">
        <div class="dash-tiles">
          ${tile('🔥 today dose', todayMM ? todayMM + ' MET-min' : '—', today.sessions.length ? today.sessions.map(s => s.type).join(', ') : 'no sessions logged', todayMM >= 100 ? 'good' : todayMM > 0 ? 'warn' : '')}
          ${tile('📅 week active', totAct + 'm', actDays + ' active days', totAct >= 150 ? 'good' : totAct > 60 ? 'warn' : '')}
          ${tile('🏷 sessions', String(totSess), 'this week', totSess >= 3 ? 'good' : totSess > 0 ? 'warn' : '')}
        </div>
        <div class="dash-block">
          <div class="ex-step-top">🔥 <b class="ex-step-big">${weekMM}</b> MET-min this week <span class="ex-mm-today">· today ${todayMM}</span></div>
          <div class="ex-step-track"><div class="ex-step-fill" style="width:${weekPct}%"></div></div>
          <div class="ex-step-scale"><span>${weekPct}%</span><span>goal: ${MET_GOAL} MET-min / wk</span></div>
          <div class="dash-foot">${realSess
            ? `MET-min comes straight off heart-rate-per-minute once a watch is synced — here's a real Samsung-watch session: ${metReceipt(realSess)}.`
            : 'MET-minutes (intensity × duration) — what your clinician, PT, and nutritionist use. steps live on every other device; this is the dose that moves the needle.'
          }</div>
        </div>
        <div class="dash-block ex-tl-block ex-scope">
          <div class="dash-block-label">activity · time of day</div>
          <div class="ex-tl-wrap"><div class="ex-time-axis">${axis}</div><div class="ex-days-grid">${dayCols}</div></div>
          <div class="ex-legend">
            <div class="ex-leg-item"><div class="ex-leg-dot t-light"></div>light (walk/yoga)</div>
            <div class="ex-leg-item"><div class="ex-leg-dot t-mod"></div>moderate</div>
            <div class="ex-leg-item"><div class="ex-leg-dot t-hard"></div>hard</div>
            <div class="ex-leg-item"><div class="ex-leg-dot t-intense"></div>intense</div>
          </div>
        </div>
        </div><div class="dash-sub-slider" data-sub="osc" title="drag to resize">⇕</div></div>
        <div class="dash-sub dash-journal-card">
        <div class="dash-sub-head" data-sub="journal"><img class="jrnl-ico" src="cards/dashboards/wellness-journal.png" alt=""> THE JOURNAL<span class="dash-sub-caret">▼</span></div>
        <div class="dash-sub-body">
        <div class="journal-pages">
        <div class="journal-page left">
        <button class="ex-print" title="a clean one-page report — print it or Save as PDF for your clinician">🖨 print this week for your clinician</button>
        <div class="dash-block">
          <div class="dash-block-label">averages</div>
          <div class="ex-avg-grid">
            <div class="ex-avg-card cool"><div class="ex-avg-val">${avgMM || '—'}</div><div class="ex-avg-lbl">avg MET-min / active day</div><div class="ex-avg-goal">~85 ≈ a brisk session</div></div>
            <div class="ex-avg-card warn"><div class="ex-avg-val">${totAct}</div><div class="ex-avg-lbl">total active min</div><div class="ex-avg-goal">goal 150+ min / wk</div></div>
            <div class="ex-avg-card good"><div class="ex-avg-val">${totSess}</div><div class="ex-avg-lbl">sessions logged</div><div class="ex-avg-goal">this week</div></div>
            <div class="ex-avg-card"><div class="ex-avg-val">${bestLbl}</div><div class="ex-avg-lbl">most active day</div><div class="ex-avg-goal">${bestDay && metMin(bestDay.sessions) > 0 ? Math.round(metMin(bestDay.sessions)) + ' MET-min' : ''}</div></div>
          </div>
        </div>
        <div class="dash-block">
          <div class="dash-block-label">quick log · tap to fill</div>
          <div class="ex-presets">${presetsHTML}</div>
        </div>
        </div>
        <div class="journal-page right">
        <div class="dash-block">
          <div class="dash-block-label">log a session — or snap it: a watch, a fitness app, a screenshot</div>
          ${OZ_SNAP_ROW}
          <div class="ex-log-form">
            <div class="ex-log-row">
              <label class="ex-log-field ex-lf-name">activity<input class="ex-log-in" type="text" placeholder="Yoga, Hügelkultur, Walk…"></label>
              <label class="ex-log-field">start<input class="ex-log-in" type="time" value="10:00"></label>
              <label class="ex-log-field ex-lf-dur">min<input class="ex-log-in" type="number" placeholder="60" min="1" max="720"></label>
            </div>
            <div class="ex-log-row">
              <label class="ex-log-field ex-lf-met">intensity (MET)<select class="ex-log-in">
                <option value="1.5">Restorative — MET 1.5</option>
                <option value="2.0">Very light — MET 2.0</option>
                <option value="3.0">Yoga flow — MET 3.0</option>
                <option value="3.5" selected>Light / yoga teach — MET 3.5</option>
                <option value="4.0">Moderate — MET 4.0</option>
                <option value="4.5">Strength — MET 4.5</option>
                <option value="5.0">Walk fast — MET 5.0</option>
                <option value="5.5">Heavy labor — MET 5.5</option>
                <option value="6.0">Vigorous — MET 6.0</option>
                <option value="7.0">HIIT — MET 7.0</option>
              </select></label>
              <label class="ex-log-field">date<input class="ex-log-in" type="date" value="${todayIso()}"></label>
              <button class="ex-log-submit">LOG IT</button>
            </div>
            <div class="ex-log-status"></div>
            <button class="ex-preset-add" title="save this activity + intensity as a quick-log preset">＋ save as preset</button>
          </div>
        </div>
        <div class="dash-block">
          <div class="dash-block-label">notes</div>
          <textarea class="jrnl-note" spellcheck="false" placeholder="how'd it feel? · what you noticed · a thought for next time…">${(() => { try { return (localStorage.getItem('toto_ex_notes') || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') } catch (_) { return '' } })()}</textarea>
        </div>
        </div></div>
        </div><div class="dash-sub-slider" data-sub="journal" title="drag to resize">⇕</div></div>`
    }

    // 🖨 the clinician report — a clean one-page HTML of THIS week (nav + print again for more weeks). prints
    //    via a hidden iframe (reliable on file:// + no popup blocker) → the user hits print or Save as PDF.
    function printWeek() {
      const days = getWeek()
      const totSess = days.reduce((s, d) => s + d.sessions.length, 0)
      const totAct  = days.reduce((s, d) => s + (d.active_min || 0), 0)
      const actDays = days.filter(d => d.active_min > 0).length
      const weekMM  = Math.round(days.reduce((s, d) => s + metMin(d.sessions), 0))
      const avgMM   = actDays ? Math.round(weekMM / actDays) : 0
      const dl = d => { const x = new Date(d.date + 'T12:00:00'); return DAY_ABR[x.getDay()] + ' ' + (x.getMonth() + 1) + '/' + x.getDate() }
      const range = dl(days[0]) + ' → ' + dl(days[days.length - 1])
      const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
      const rows = days.map(d => {
        const dmm = Math.round(metMin(d.sessions))
        const sess = d.sessions.length
          ? d.sessions.map(s => `${esc(s.type)} · ${esc(s.start)} · ${s.duration_min} min · MET ${s.met}${s.hr_mean ? ' · HR ' + s.hr_mean : ''}`).join('<br>')
          : '<span class="z">rest</span>'
        return `<tr><td class="d">${dl(d)}</td><td class="n">${d.active_min || 0}</td><td class="n">${dmm}</td><td>${sess}</td></tr>`
      }).join('')
      let notes = ''; try { notes = esc(localStorage.getItem('toto_ex_notes') || '').replace(/\n/g, '<br>') } catch (_) {}
      const now = new Date().toLocaleDateString()
      const pct = Math.min(100, Math.round(weekMM / MET_GOAL * 100))
      // the person's repertoire (the quick-log presets) — so the clinician can ask about these even if a given week is quiet
      const metBand = m => m < 3 ? 'light' : m < 6 ? 'moderate' : 'vigorous'
      const presetRows = PRESETS.map(p => `<tr><td class="d">${esc(p.type)}</td><td class="n">${p.dur} min</td><td class="n">${p.met}</td><td>${metBand(p.met)}</td></tr>`).join('')
      // session-prep format (per Sum's LCSW template): title · scope summary table · red emoji sections ·
      // bold-lead bullets · ⚠ callouts · day table · notes · footer with refs. wellness data, clinical layout.
      const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Exercise Report · ${range}</title><style>
        @page { margin: 16mm; } * { box-sizing: border-box; }
        body { font: 13px/1.55 -apple-system, "Segoe UI", Roboto, sans-serif; color: #1a1a1a; margin: 0; }
        h1 { font-size: 24px; font-weight: 800; margin: 0 0 2px; color: #111; }
        .subtitle { color: #555; font-size: 13px; }
        hr { border: none; border-top: 1px solid #ddd; margin: 14px 0; }
        table.scope { width: 100%; border-collapse: collapse; margin: 4px 0 20px; font-size: 13px; }
        table.scope th { background: #334155; color: #fff; text-align: left; padding: 9px 12px; font-weight: 700; }
        table.scope th.t { text-align: right; width: 150px; }
        table.scope td { padding: 8px 12px; border: 1px solid #e2e2e2; }
        table.scope td.t { text-align: right; white-space: nowrap; color: #555; font-variant-numeric: tabular-nums; }
        table.scope tr.note td { background: #fdf6e3; }
        h2 { font-size: 16px; font-weight: 800; color: #b91c1c; margin: 22px 0 8px; }
        ul { margin: 0 0 6px; padding-left: 20px; } li { margin-bottom: 5px; } li b { color: #111; }
        .warn { color: #b45309; margin: 6px 0; font-weight: 600; }
        table.days { width: 100%; border-collapse: collapse; font-size: 12px; margin: 4px 0; }
        table.days th, table.days td { text-align: left; padding: 7px 9px; border-bottom: 1px solid #e2e2e2; vertical-align: top; }
        table.days th { color: #555; text-transform: uppercase; font-size: 10px; letter-spacing: .5px; }
        table.days td.d { font-weight: 600; white-space: nowrap; } table.days td.n { text-align: right; font-variant-numeric: tabular-nums; width: 72px; } .z { color: #999; }
        .notes-box { border: 1px solid #ddd; border-radius: 6px; padding: 11px 14px; margin: 4px 0; white-space: pre-wrap; }
        .foot { margin-top: 22px; font-size: 11px; color: #666; border-top: 1px solid #ddd; padding-top: 10px; }
      </style></head><body>
        <h1>Exercise Report &mdash; ${range} 🏃</h1>
        <div class="subtitle">Sum Bhodi  |  Activity &middot; MET-minutes  &middot;  generated ${now}</div>
        <hr>
        <table class="scope">
          <tr><th>THIS WEEK &mdash; Activity Summary</th><th class="t">Value</th></tr>
          <tr><td>MET-minutes (intensity &times; duration)</td><td class="t">${weekMM} / ${MET_GOAL} &middot; ${pct}%</td></tr>
          <tr><td>Average MET-min / active day</td><td class="t">${avgMM}</td></tr>
          <tr><td>Total active minutes</td><td class="t">${totAct} min</td></tr>
          <tr><td>Sessions logged</td><td class="t">${totSess}</td></tr>
          <tr class="${actDays < 3 ? 'note' : ''}"><td>Active days</td><td class="t">${actDays} / 7</td></tr>
        </table>
        <h2>📊 What the numbers mean</h2>
        <ul>
          <li><b>MET-minutes &mdash;</b> intensity (MET) &times; duration &mdash; the dose a clinician, PT, and nutritionist use. WHO target &asymp; 500&ndash;600 MET-min/week of moderate activity. Steps live on every other device; this is what moves the needle.</li>
          <li><b>This week &mdash;</b> ${weekMM} MET-min (${pct}% of the ${MET_GOAL} goal) across ${totSess} session${totSess === 1 ? '' : 's'} on ${actDays} of 7 days.</li>
        </ul>
        ${actDays < 3 ? '<div class="warn">⚠ Fewer than 3 active days this week &mdash; flagged for review.</div>' : ''}
        <h2>📅 Day by day</h2>
        <table class="days"><thead><tr><th>Day</th><th style="text-align:right">Active</th><th style="text-align:right">MET-min</th><th>Sessions (type &middot; start &middot; duration &middot; MET &middot; HR)</th></tr></thead><tbody>${rows}</tbody></table>
        <h2>📋 Usual activities &mdash; the quick-log menu</h2>
        <p style="color:#555;margin:0 0 8px">What this person does regularly &mdash; worth asking about even if it's not in this week's log:</p>
        <table class="days"><thead><tr><th>Activity</th><th style="text-align:right">Typical</th><th style="text-align:right">MET</th><th>Intensity</th></tr></thead><tbody>${presetRows}</tbody></table>
        ${notes ? `<h2>📝 Notes</h2><div class="notes-box">${notes}</div>` : ''}
        <div class="foot">Prepared with toto &middot; heart-rate-derived MET where a watch was synced.<br>This report covers <b>${range}</b>. Nav to other weeks and print again to assemble a multi-week record for your appointment.</div>
      </body></html>`
      let f = document.getElementById('ex-print-frame'); if (f) f.remove()
      f = document.createElement('iframe'); f.id = 'ex-print-frame'; f.style.cssText = 'position:fixed;width:0;height:0;border:0;right:0;bottom:0;'
      document.body.appendChild(f)
      const doc = f.contentWindow.document; doc.open(); doc.write(html); doc.close()
      setTimeout(() => { try { f.contentWindow.focus(); f.contentWindow.print() } catch (_) {} }, 350)
    }

    // ── 💪 exercise profile — "just how you like to exercise" · wellness reads it (engine.js) so it never re-asks ──
    const EX_PROFILE_HTML = `
      <div class="sp-block">
        <div class="sp-head">💪 exercise profile — wellness reads this · no repeat questions</div>
        <div class="sp-grid">
          <label class="sp-full">what I love to do (the movement I'll actually keep doing)<textarea class="sp-ta" data-k="favorites" rows="2" placeholder="teaching yoga, long walks, hügelkultur + garden beds by hand"></textarea></label>
          <label>how often I aim to move<input type="text" class="sp-in" data-k="frequency" placeholder="something most days · yoga 5×/wk"></label>
          <label>best time of day<input type="text" class="sp-in" data-k="time" placeholder="early morning · between classes"></label>
          <label class="sp-full">intensity I like (and what's too much)<textarea class="sp-ta" data-k="intensity" rows="2" placeholder="mostly light–moderate · restorative on teaching days · the odd hard garden day"></textarea></label>
          <label class="sp-full">what I'm training for (the why)<textarea class="sp-ta" data-k="goals" rows="2" placeholder="mobility + longevity · strong enough to teach + farm · stress + mood"></textarea></label>
          <label class="sp-full">injuries · limits · what to avoid<textarea class="sp-ta" data-k="limits" rows="2" placeholder="easy on the low back · no high-impact · listen to the knees"></textarea></label>
          <label class="sp-full">what gets me moving (and what stalls me)<textarea class="sp-ta" data-k="motivation" rows="2" placeholder="morning light + a plan · ADHD — if it's not on the calendar it doesn't happen"></textarea></label>
          <label class="sp-full">background (anything wellness should know without asking)<textarea class="sp-ta" data-k="background" rows="3" placeholder="18-yr yoga teacher, permaculture by hand, clinical insomniac — movement is also sleep + mood medicine"></textarea></label>
        </div>
        <button class="sp-save">save profile</button>
        <div class="sp-msg"></div>
      </div>
      <div class="sp-divider"></div>`
    const exGear = document.createElement('button')
    exGear.className = 'dash-gear'; exGear.type = 'button'; exGear.innerHTML = (window.OZ_GEAR_SVG || '⚙')
    exGear.title = 'exercise profile — how you like to move · wellness reads this so it never re-asks'
    const el = dashCard('exercise', 'cards/wellness/exercise.png', 'EXERCISE', '', { badge: 'real · Mar 2026', live: true, badgeTitle: 'Sum’s real activity data · Google Fit + Samsung Health · shared with consent', gear: exGear })
    const cardBody = el.querySelector('.card-body')          // GROW the card with its content → the DESK doom-scrolls (not a capped inner box)
    cardBody.style.overflowY = 'auto'   // (Sum 2026-07-10) interior scroll back ON — the card was growing + getting clipped by .card{overflow:hidden} → cut off
    const dashBody = el.querySelector('.dash-body')
    dashBody.style.flex = 'none'; dashBody.style.overflowY = 'visible'   // the desk scrolls between cards; the osc keeps its OWN inner scroll
    // (the 🧘 spa top bar is now the .p-dash skin in dashboards.css — food · sleep · exercise all inherit it)

    const subOpen = { osc: false, journal: false }   // (Sum 2026-08-17) BOTH start collapsed; the card scrolls well, so neither needs to hog the view    // both closed; each toggles on its own
    const subHeight = { osc: 520, journal: 560 }     // osc: FIXED height → scrolls inside, ⇕ stays visible. journal: a MIN floor → grows to the whole book.
    function applySubs() {
      dashBody.querySelectorAll('.dash-sub').forEach(s => {
        const k = s.classList.contains('dash-osc') ? 'osc' : 'journal'
        s.classList.toggle('collapsed', !subOpen[k])
        const b = s.querySelector('.dash-sub-body'); if (!b) return
        if (k === 'osc') { b.style.minHeight = ''; b.style.height = subHeight.osc + 'px' }   // fixed → the scope SCROLLS inside + the ⇕ is always in view
        else { b.style.height = 'auto'; b.style.minHeight = subHeight.journal + 'px' }        // the journal grows to show the whole book
      })
    }
    function render() { dashBody.innerHTML = buildBody(); applySubs() }
    render()

    // ⭐ REPAINT ON EVERY EDIT (Sum 2026-08-25) — he logged 20 minutes of yoga, the log took it, and this
    //    card sat stale until he scrolled to a different day and back. The conductor now fires
    //    'oz-card-dirty' from its ONE tool choke point (every lane passes through it), so this repaints per
    //    EDIT, not per save — the draft strip above fills slot by slot while he watches the bot work.
    //    The render fn lives on window, not in this closure: reopening the card makes a NEW render, and a
    //    listener closed over the old one would quietly repaint a detached node forever.
    window.__exRepaint = render
    if (!window.__exDirtyWired) {
      window.__exDirtyWired = true
      window.addEventListener('oz-card-dirty', e => {
        try { const d = e && e.detail
              if (window.__exRepaint && (!d || d.card === 'exercise')) window.__exRepaint() } catch (_) {}
      })
    }

    // each sub-card's ⇕ slider — drag to set THAT sub-body's height (it scrolls inside) instead of the whole card
    dashBody.addEventListener('mousedown', e => {
      const sl = e.target.closest('.dash-sub-slider'); if (!sl) return
      e.preventDefault(); e.stopPropagation()
      const k = sl.dataset.sub, b = sl.parentElement.querySelector('.dash-sub-body'); if (!b) return
      const sy = e.clientY, sh = b.offsetHeight
      document.body.classList.add('resizing')
      const move = ev => { const h = Math.max(80, sh + ev.clientY - sy); if (k === 'osc') { b.style.height = h + 'px' } else { b.style.minHeight = h + 'px' } subHeight[k] = h }
      const up = () => { document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); document.body.classList.remove('resizing') }
      document.addEventListener('mousemove', move); document.addEventListener('mouseup', up)
    })

    // the journal's notes — persist as you type (survives re-render; restored in buildBody from toto_ex_notes)
    dashBody.addEventListener('input', e => { const n = e.target.closest('.jrnl-note'); if (n) { try { localStorage.setItem('toto_ex_notes', n.value) } catch (_) {} } })

    dashBody.addEventListener('click', e => {
      const snap = e.target.closest('.fc-att')   // 📸/🖥️/📎 → the wellness bot's attach engine
      if (snap) { e.stopPropagation(); ozSnapTo('wellness', snap.dataset.att); return }
      // collapse / expand the osc or journal sub-card (persist via subOpen)
      const subHead = e.target.closest('.dash-sub-head')
      if (subHead) { e.stopPropagation(); const k = subHead.dataset.sub; subOpen[k] = !subOpen[k]; applySubs(); return }   // (Sum 2026-08-17) INDEPENDENT — you used to have to open one to collapse the other
      // week nav — same pattern as sleep card (fc-logctrl / sNav)
      const tdy = e.target.closest('[data-today]'); if (tdy) { e.stopPropagation(); end = todayIso(); render(); return }
      const arr = e.target.closest('.fc-arrow'); if (arr) { e.stopPropagation(); end = dShiftIso(end, +arr.dataset.arrow); render(); return }
      // 🖨 print this week as a clinician report
      const pr = e.target.closest('.ex-print')
      if (pr) { e.stopPropagation(); printWeek(); return }
      // delete a preset — the ✕ on a chip (left page)
      const pdel = e.target.closest('.ex-preset-x')
      if (pdel) { e.stopPropagation(); PRESETS.splice(+pdel.dataset.del, 1); savePresets(); render(); return }
      // save the current form as a new preset (right page)
      const padd = e.target.closest('.ex-preset-add')
      if (padd) {
        e.stopPropagation()
        const ni = dashBody.querySelector('.ex-log-in[type=text]'), di = dashBody.querySelector('.ex-log-in[type=number]'), sel = dashBody.querySelector('.ex-log-form select')
        const name = ni && ni.value.trim(), dur = (di && parseInt(di.value)) || 30, met = sel ? parseFloat(sel.value) : 3.5
        const sta = dashBody.querySelector('.ex-log-status')
        if (!name) { if (sta) sta.textContent = 'type an activity first, then save it'; return }
        if (PRESETS.some(p => p.type.toLowerCase() === name.toLowerCase())) { if (sta) sta.textContent = `"${name}" is already a preset`; return }
        PRESETS.push({ type: name, dur, met }); savePresets(); render(); return
      }
      // preset — fills the log form
      const preset = e.target.closest('.ex-preset')
      if (preset) {
        e.stopPropagation()
        dashBody.querySelectorAll('.ex-preset').forEach(b => b.classList.remove('active'))
        preset.classList.add('active')
        const ni  = dashBody.querySelector('.ex-log-in[type=text]')
        const di  = dashBody.querySelector('.ex-log-in[type=number]')
        const sel = dashBody.querySelector('.ex-log-form select')
        if (ni)  ni.value  = preset.dataset.type
        if (di)  di.value  = preset.dataset.dur
        if (sel) { let best = null, bestDiff = Infinity; [...sel.options].forEach(o => { const diff = Math.abs(parseFloat(o.value) - parseFloat(preset.dataset.met)); if (diff < bestDiff) { bestDiff = diff; best = o } }); if (best) sel.value = best.value }
        return
      }
      // log submit — persist + re-render
      const sub = e.target.closest('.ex-log-submit')
      if (!sub) return
      e.stopPropagation()
      const ni  = dashBody.querySelector('.ex-log-in[type=text]')
      const ti  = dashBody.querySelector('.ex-log-in[type=time]')
      const di  = dashBody.querySelector('.ex-log-in[type=number]')
      const sel = dashBody.querySelector('.ex-log-form select')
      const dti = dashBody.querySelector('.ex-log-in[type=date]')
      const sta = dashBody.querySelector('.ex-log-status')
      const name = ni && ni.value.trim(), dur = di && parseInt(di.value)
      if (!name || !dur) { if (sta) sta.textContent = 'need activity + duration'; return }
      const [hh, mm] = ((ti && ti.value) || '10:00').split(':').map(Number)
      const ampm = hh >= 12 ? 'PM' : 'AM', h12 = hh % 12 || 12
      const startFmt = `${h12}:${String(mm).padStart(2, '0')} ${ampm}`
      const met  = sel ? parseFloat(sel.value) : 3.5
      const date = (dti && dti.value) || new Date().toISOString().slice(0, 10)
      const kcal = Math.round(met * 132 * (dur / 60))
      try {
        const stored = JSON.parse(localStorage.getItem('toto_exercise_log') || '[]')
        stored.push({ date, type: name, start: startFmt, duration_min: dur, met })
        localStorage.setItem('toto_exercise_log', JSON.stringify(stored))
      } catch (_) {}
      render()
      const newSta = dashBody.querySelector('.ex-log-status')
      if (newSta) { newSta.textContent = `✓ logged ${dur}min ${name} — ~${kcal} kcal`; setTimeout(() => { if (newSta) newSta.textContent = '' }, 4000) }
    })

    // ── 💪 exercise profile: ⚙️ gear panel (same pattern as food / sleep) ──
    const EP_KEY = 'toto_exercise_profile'
    const exPanel = document.createElement('div'); exPanel.className = 'sleep-setup'; exPanel.hidden = true
    exPanel.innerHTML = `<div class="sleep-setup-head">⚙️ exercise settings</div>` + EX_PROFILE_HTML + dataInMini('exercise') + `<div class="ls-close-row"><button class="ls-close ex-setup-x">✕ close settings</button></div>`
    cardBody.appendChild(exPanel)   // into the BODY → head + ⚙️ gear stay visible (gear toggles)
    // GLOBAL settings rule: settings OR content. .sleep-setup is position:absolute inset:0, so the auto-height
    // body needs a definite height while open (else the panel collapses to a sliver — the sleep bug).
    const epSetOpen = on => {
      [...cardBody.children].forEach(n => { if (n !== exPanel) { n.hidden = on; n.style.display = on ? 'none' : '' } })
      exPanel.hidden = !on
      if (on) el.classList.remove('collapsed')   // open the wellness station so the panel is visible
      cardBody.style.overflowY = 'auto'   // (Sum 2026-07-10) interior scroll back ON — the card was growing + getting clipped by .card{overflow:hidden} → cut off   // panel flows → body grows, desk scrolls
      if (on) epLoad()
    }
    const epFields = () => exPanel.querySelectorAll('[data-k]')
    const epLoad = () => { try { const p = JSON.parse(localStorage.getItem(EP_KEY) || '{}'); epFields().forEach(f => { if (p[f.dataset.k] != null) f.value = p[f.dataset.k] }) } catch (_) {} }
    const epSave = () => {
      const p = {}; epFields().forEach(f => { if (f.value && f.value.trim()) p[f.dataset.k] = f.value.trim() })
      localStorage.setItem(EP_KEY, JSON.stringify(p))
      const m = exPanel.querySelector('.sp-msg'); if (m) { m.textContent = '✓ saved'; setTimeout(() => { m.textContent = '' }, 1800) }
    }
    // the Samsung .zip road — the SAME archive the sleep import reads; the exercise csv is already in it
    const exFile = document.createElement('input'); exFile.type = 'file'; exFile.accept = '.zip'; exFile.hidden = true; exPanel.appendChild(exFile)
    exFile.addEventListener('change', async () => {
      const f = exFile.files && exFile.files[0]; if (!f) return
      const msg = exPanel.querySelector('.ozin-msg'); if (msg) msg.textContent = 'reading the zip…'
      try { const n = await window.importSamsungExercise(f)
        if (msg) msg.textContent = `✓ ${n} session${n === 1 ? '' : 's'} logged — reopen the card to see them`
        render()
      } catch (err) { if (msg) msg.textContent = '✕ ' + ((err && err.message) || err) }   // say what went wrong, never fail silent
      exFile.value = ''
    })
    exPanel.addEventListener('click', e => { e.stopPropagation()
      if (e.target.closest('.ozin-imp')) { exFile.click(); return }
      if (e.target.closest('.ex-setup-x')) { epSetOpen(false); return } if (e.target.closest('.sp-save')) epSave() })
    exGear.addEventListener('click', e => { e.stopPropagation(); epSetOpen(exPanel.hidden) })

    return el
  }


  // ── ⏱ → 💪 EXPORT FROM THE CLOCK (Sum 2026-07-21: "big bar button, export to exercise… opens
  //    exercise with total minutes and time filled in, and gives wellness your lap times or
  //    intervals to ask you what you were doing, so it can help you guess METs per minute").
  //    The clock cards live in an IFRAME, so they call parent.OZ_EXPORT_EXERCISE(payload).
  //    payload = { min, startISO, name?, laps?:[ms], intervals?:[{n,ms}], source:'stopwatch'|'timer' }
  window.OZ_EXPORT_EXERCISE = function (payload) {
    payload = payload || {}
    try { if (window.toggleCard) window.toggleCard('exercise', true) } catch (_) {}
    let tries = 0
    const fill = () => {
      const form = document.querySelector('.ex-log-form')
      if (!form) { if (tries++ < 40) return setTimeout(fill, 120); return }   // the card mounts async
      const nameIn = form.querySelector('.ex-lf-name input')
      const timeIn = form.querySelector('input[type="time"]')
      const minIn = form.querySelector('.ex-lf-dur input')
      const dateIn = form.querySelector('input[type="date"]')
      const p2 = n => String(n).padStart(2, '0')
      const d = payload.startISO ? new Date(payload.startISO) : new Date()
      if (minIn && payload.min) minIn.value = Math.max(1, Math.round(payload.min))
      if (timeIn) timeIn.value = p2(d.getHours()) + ':' + p2(d.getMinutes())
      if (dateIn) dateIn.value = d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate())
      if (nameIn && payload.name) nameIn.value = payload.name
      else if (nameIn) nameIn.focus()                                        // the one thing only you know
      const st = form.querySelector('.ex-log-status')
      if (st) st.textContent = Math.round(payload.min || 0) + ' min from the ' + (payload.source || 'clock') + ' — name it, then LOG IT.'
      exAskWellness(payload)
    }
    fill()
  }
  // hand the SPLITS to wellness so it can ask what you were doing and help you pick an honest MET
  function exAskWellness(p) {
    const fmt = ms => { const t = Math.floor(ms / 1000); return Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0') }
    let detail = ''
    if (p.intervals && p.intervals.length) detail = p.intervals.map(i => (i.n || 'interval') + ' ' + fmt(i.ms)).join(' · ')
    else if (p.laps && p.laps.length) {
      const sp = p.laps.map((t, i) => t - (p.laps[i - 1] || 0))
      detail = sp.map((ms, i) => 'lap ' + (i + 1) + ' ' + fmt(ms)).join(' · ')
    }
    if (!detail) return
    const msg = 'I just finished ' + Math.round(p.min || 0) + ' minutes on the ' + (p.source || 'clock') + '.\n'
      + detail + '\n\nWhat was I doing? Ask me if you need to — then help me pick a MET for it so the log is honest.'
    try { if (window.ozAskBot) window.ozAskBot('wellness', msg) } catch (_) {}
  }
